// An angled, top-down "kingdom" view you pan, rotate and zoom instead of walking around.
const camTarget = new THREE.Vector3(WORLD_SIZE/2, 0, WORLD_SIZE/2);
let camYaw = Math.PI/4;
let camPitch = THREE.MathUtils.degToRad(58);
let camDistance = 30;

function updateCamera(dt){
  const panSpeed = 16*dt*(camDistance/28);
  const fwd = new THREE.Vector3(-Math.sin(camYaw), 0, -Math.cos(camYaw));
  const right = new THREE.Vector3(Math.cos(camYaw), 0, -Math.sin(camYaw));
  if(keys.KeyW || keys.ArrowUp)    camTarget.addScaledVector(fwd, panSpeed);
  if(keys.KeyS || keys.ArrowDown)  camTarget.addScaledVector(fwd, -panSpeed);
  if(keys.KeyD || keys.ArrowRight) camTarget.addScaledVector(right, panSpeed);
  if(keys.KeyA || keys.ArrowLeft)  camTarget.addScaledVector(right, -panSpeed);
  if(keys.KeyQ) camYaw -= 1.1*dt;
  if(keys.KeyE) camYaw += 1.1*dt;
  var _bounds = legacyMode ? {min:0, max:LEGACY_MAP_SIZE} : {min:2, max:WORLD_SIZE-2};
  camTarget.x = Math.max(_bounds.min, Math.min(_bounds.max, camTarget.x));
  camTarget.z = Math.max(_bounds.min, Math.min(_bounds.max, camTarget.z));
  const px = camTarget.x + camDistance*Math.sin(camYaw)*Math.cos(camPitch);
  const pz = camTarget.z + camDistance*Math.cos(camYaw)*Math.cos(camPitch);
  const py = camTarget.y + camDistance*Math.sin(camPitch);
  camera.position.set(px, py, pz);
  camera.lookAt(camTarget.x, camTarget.y, camTarget.z);
}

function updateVillagers(dt, simTime){
  villagers.forEach(function(v){
    if(Math.abs(v.tx-v.x) > 0.02 || Math.abs(v.tz-v.z) > 0.02){
      const dx = v.tx - v.x, dz = v.tz - v.z;
      const dist = Math.hypot(dx,dz);
      const step = v.speed*dt;
      if(dist <= step){ v.x = v.tx; v.z = v.tz; }
      else { v.x += dx/dist*step; v.z += dz/dist*step; }
      v.group.rotation.y = Math.atan2(dx,dz);
    } else if(!v.job && simTime > v.wanderAt){
      v.tx = Math.max(1, Math.min(WORLD_SIZE-2, v.x + (Math.random()*10-5)));
      v.tz = Math.max(1, Math.min(WORLD_SIZE-2, v.z + (Math.random()*10-5)));
      v.wanderAt = simTime + 5 + Math.random()*7;
    }
    v.y = getGroundHeight(v.x, v.z);
    v.group.position.set(v.x, v.y, v.z);
  });
}

const MINE_WORK_TIME = 5;
const SECONDS_PER_BLOCK = 0.5;

function assignJob(v, job){
  job.workLeft = MINE_WORK_TIME;
  job.working = false;
  v.job = job;
  v.tx = job.tx;
  v.tz = job.tz;
  showWorldWarning('On the way…', 2000);
}

function updateJobs(dt){
  villagers.forEach(function(v){
    const j = v.job;
    if(!j) return;
    const dist = Math.hypot(j.tx - v.x, j.tz - v.z);
    if(dist > 0.6){ j.working = false; return; }
    if(j.kind === 'mine' && !world.has(key(j.x,j.y,j.z))){ v.job = null; return; }
    if(j.kind === 'chop' && trees.indexOf(j.treeRef) === -1){ v.job = null; return; }
    j.working = true;
    if(j.kind === 'build'){
      j.elapsed += dt;
      const shouldHave = Math.min(j.blocks.length, Math.floor(j.elapsed / SECONDS_PER_BLOCK));
      while(j.placed < shouldHave){
        placeLayoutBlock(j.blocks[j.placed]);
        j.placed++;
      }
      if(selectedVillager === v){
        const statusEl = document.getElementById('world-status');
        if(statusEl) statusEl.textContent = 'Building… ' + j.placed + '/' + j.blocks.length + ' blocks';
      }
      if(j.placed >= j.blocks.length){
        if(j.buildingType === 'house'){ houses.push({ x0:j.x0, z0:j.z0, size:j.size, lastGrowth:simTime }); decorateHouse(j.x0, j.z0, j.size); }
        else farms.push({ x0:j.x0, z0:j.z0, size:j.size, lastGrowth:simTime });
        v.job = null;
        if(selectedVillager === v){
          const statusEl = document.getElementById('world-status');
          if(statusEl) statusEl.textContent = '';
        }
      }
      return;
    }
    j.workLeft -= dt;
    if(selectedVillager === v){
      const statusEl = document.getElementById('world-status');
      if(statusEl) statusEl.textContent = (j.kind === 'chop' ? 'Chopping… ' : 'Digging… ') + Math.max(0, j.workLeft).toFixed(1) + 's';
    }
    if(j.workLeft <= 0) completeJob(v);
  });
}

function completeJob(v){
  const j = v.job;
  v.job = null;
  let px, pz, colorHex;
  if(j.kind === 'chop'){
    px = j.treeRef.x; pz = j.treeRef.z;
    colorHex = 0x6b4a2c;
    chopTree(j.treeRef);
  } else {
    px = j.x + 0.5; pz = j.z + 0.5;
    colorHex = BLOCK_TYPES[j.typeIndex].color;
    removeBlockAt(j.x, j.y, j.z);
    addToInventory(j.typeIndex, 1);
  }
  spawnShards(px, getGroundHeight(px,pz) + 0.6, pz, colorHex);
  if(selectedVillager === v){
    const statusEl = document.getElementById('world-status');
    if(statusEl) statusEl.textContent = '';
  }
}

const shards = [];
const shardGeo = new THREE.BoxGeometry(0.14,0.14,0.14);

function spawnShards(x,y,z,colorHex){
  for(let i=0;i<7;i++){
    const mat = new THREE.MeshLambertMaterial({ color:colorHex, transparent:true, opacity:1 });
    const m = new THREE.Mesh(shardGeo, mat);
    m.position.set(x + (Math.random()-0.5)*0.3, y, z + (Math.random()-0.5)*0.3);
    scene.add(m);
    shards.push({
      mesh:m,
      vx:(Math.random()-0.5)*2.2,
      vy:2 + Math.random()*1.5,
      vz:(Math.random()-0.5)*2.2,
      life:0,
      maxLife:0.7 + Math.random()*0.3
    });
  }
}

function updateShards(dt){
  for(let i=shards.length-1;i>=0;i--){
    const s = shards[i];
    s.life += dt;
    s.vy -= 9*dt;
    s.mesh.position.x += s.vx*dt;
    s.mesh.position.y += s.vy*dt;
    s.mesh.position.z += s.vz*dt;
    s.mesh.rotation.x += dt*4;
    s.mesh.rotation.y += dt*3;
    s.mesh.material.opacity = Math.max(0, 1 - s.life/s.maxLife);
    if(s.life >= s.maxLife){
      scene.remove(s.mesh);
      s.mesh.material.dispose();
      shards.splice(i,1);
    }
  }
}

function updateSky(t){
  const cycle = (t % DAY_LENGTH) / DAY_LENGTH;
  const angle = cycle*Math.PI*2;
  const radius = 160;
  const cx = WORLD_SIZE/2, cz = WORLD_SIZE/2;
  sunMesh.position.set(cx + radius*Math.cos(angle), radius*Math.sin(angle), cz);
  moonMesh.position.set(cx + radius*Math.cos(angle+Math.PI), radius*Math.sin(angle+Math.PI), cz);
  const dayFactor = Math.max(0, Math.sin(angle));
  sunLight.position.copy(sunMesh.position);
  sunLight.intensity = 0.15 + dayFactor*0.85;
  sunLight.color.setHex(dayFactor > 0.15 ? 0xfff3d6 : 0x8fa5d6);
  hemi.intensity = 0.3 + dayFactor*0.65;
  const skyDay = new THREE.Color(0x8fc7e8);
  const skyNight = new THREE.Color(0x0b1020);
  const skyColor = skyNight.clone().lerp(skyDay, dayFactor);
  scene.background.copy(skyColor);
  worldFog.color.copy(skyColor);
  stars.material.opacity = 1 - dayFactor;
  if(wbFx) wbFx.sky(dayFactor);
}

