function serializeWorld(){
  const blocks = [];
  world.forEach(function(mesh){
    blocks.push([mesh.userData.x, mesh.userData.y, mesh.userData.z, mesh.userData.typeIndex]);
  });
  return {
    version: 1,
    simTime: simTime,
    inventory: inventory.slice(),
    blocks: blocks,
    trees: trees.map(function(t){ return [t.x, t.z]; }),
    farms: farms.map(function(f){ return [f.x0, f.z0, f.size, f.lastGrowth]; }),
    houses: houses.map(function(h){ return [h.x0, h.z0, h.size, h.lastGrowth]; }),
    villagers: villagers.map(function(v){ return [v.x, v.z, v.tx, v.tz]; }),
    camera: { x: camTarget.x, z: camTarget.z, yaw: camYaw, distance: camDistance }
  };
}

function serializeWorkbenchBundle(){
  var bundle={format:'Stark Workbench Complete Save',version:1,appVersion:APP_VERSION,savedAt:new Date().toISOString(),world:serializeWorld()};
  try{ bundle.arcade=JSON.parse(JSON.stringify(getProfile())); }catch(e){ bundle.arcade=null; }
  try{ bundle.aiMemory=JSON.parse(JSON.stringify(getMemories())); }catch(e){ bundle.aiMemory=[]; }
  try{ bundle.aiHistory=JSON.parse(JSON.stringify(assistantBridge.getHistory()||[])); }catch(e){ bundle.aiHistory=[]; }
  try{ bundle.aiSettings=assistantBridge.getSettings(); }catch(e){}
  try{ bundle.education={notes:JSON.parse(localStorage.getItem('wb-study-notes')||'[]'),flashcards:JSON.parse(localStorage.getItem('wb-flashcards')||'[]'),dashboard:JSON.parse(localStorage.getItem('wb-student-dashboard')||'{}')}; }catch(e){ bundle.education={}; }
  try{ bundle.preferences={theme:localStorage.getItem('wb-theme'),accent:localStorage.getItem('wb-accent-color')}; }catch(e){}
  try{ bundle.extras={}; ['wb-myfiles-v1','wb-myfiles-stat','wb-weak-v1','wb-badges-v1','wb-streak-v1','wb-summary-count','wb-inf-day','wb-bw-maxdefs'].forEach(function(k){var v=localStorage.getItem(k); if(v!==null) bundle.extras[k]=v;}); }catch(e){}
  return bundle;
}
function serializeBlockWorldSave(){
  return { format:'Stark Workbench Block World Save', version:2, appVersion:APP_VERSION, savedAt:new Date().toISOString(), world:serializeWorld(), storage:blockWorldStorage() };
}
function downloadSave(){
  const blob = new Blob([JSON.stringify(serializeBlockWorldSave(),null,2)], { type:'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'workbench-block-world-' + new Date().toISOString().slice(0,10) + '.json';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function loadSaveData(data){
  if(data && (data.format === 'Stark Workbench User Saves' || data.format === 'Stark Workbench Full Backup')) throw new Error('That is a User saves file, not a Block World save. Restore it from the User / Saves tab.');
  if(data && data.format === 'Stark Workbench Block World Save'){ try{ restoreBlockWorldStorage(data.storage); }catch(e){} data = data.world || {}; }
  var bundle=data && data.format==='Stark Workbench Complete Save' ? data : null;
  if(bundle){ data=bundle.world||{}; try{ if(bundle.arcade){ replaceProfile(bundle.arcade); } }catch(e){} try{ if(Array.isArray(bundle.aiMemory)){ restoreMemories(bundle.aiMemory); } }catch(e){} try{ if(Array.isArray(bundle.aiHistory)){ assistantBridge.setHistory(bundle.aiHistory); } }catch(e){} try{ if(bundle.extras&&typeof bundle.extras==='object'){ Object.keys(bundle.extras).forEach(function(k){ if(/^wb-(myfiles|weak|badges|streak|summary|inf-day|bw-maxdefs)/.test(k)) localStorage.setItem(k,String(bundle.extras[k])); }); } }catch(e){} try{ if(bundle.education){ localStorage.setItem('wb-study-notes',JSON.stringify(bundle.education.notes||[])); localStorage.setItem('wb-flashcards',JSON.stringify(bundle.education.flashcards||[])); localStorage.setItem('wb-student-dashboard',JSON.stringify(bundle.education.dashboard||{})); } }catch(e){} }
  world.forEach(function(mesh){ scene.remove(mesh); });
  world.clear();
  (data.blocks || []).forEach(function(b){ addBlock(b[0], b[1], b[2], b[3]); });

  trees.slice().forEach(function(t){ scene.remove(t.group); });
  trees.length = 0;
  (data.trees || []).forEach(function(tp){ trees.push(makeTree(tp[0], tp[1], -1000)); });

  farms.length = 0;
  (data.farms || []).forEach(function(f){ farms.push({ x0:f[0], z0:f[1], size:f[2], lastGrowth:f[3] }); });
  houses.length = 0;
  houseDecorMeshes.slice().forEach(function(m){ scene.remove(m); });
  houseDecorMeshes.length = 0;
  (data.houses || []).forEach(function(h){ houses.push({ x0:h[0], z0:h[1], size:h[2], lastGrowth:h[3] }); decorateHouse(h[0], h[1], h[2]); });

  const savedVillagers = data.villagers || [];
  while(villagers.length < savedVillagers.length){
    villagers.push(makeVillager(WORLD_SIZE/2, WORLD_SIZE/2, villagerColors[villagers.length % villagerColors.length]));
  }
  while(villagers.length > savedVillagers.length){
    scene.remove(villagers.pop().group);
  }
  savedVillagers.forEach(function(vd, i){
    villagers[i].x = vd[0]; villagers[i].z = vd[1]; villagers[i].tx = vd[2]; villagers[i].tz = vd[3];
    villagers[i].job = null;
    villagers[i].y = getGroundHeight(villagers[i].x, villagers[i].z);
    villagers[i].group.position.set(villagers[i].x, villagers[i].y, villagers[i].z);
  });
  selectVillager(null);

  const savedInv = data.inventory || [0,0,0,0,0];
  inventory.splice(0, inventory.length, savedInv[0]||0, savedInv[1]||0, savedInv[2]||0, savedInv[3]||0, savedInv[4]||0, savedInv[5]||0, savedInv[6]||0);
  updateHotbarCounts();
  updateBuildingButtons();

  if(typeof data.simTime === 'number') simTime = data.simTime;
  if(data.camera){
    camTarget.set(data.camera.x, 0, data.camera.z);
    camYaw = data.camera.yaw;
    camDistance = data.camera.distance;
  }
}

