function animate(){
  requestAnimationFrame(animate);
  const now = performance.now();
  const frameMs = now - perfLastFrameAt;
  perfLastFrameAt = now;
  if(frameMs > 0 && frameMs < 1000) perfInstHz = Math.round(1000 / frameMs);
  perfFrameCount++;
  if(now - perfSampleStart >= 500){
    const avgFps = Math.round((perfFrameCount * 1000) / (now - perfSampleStart));
    perfFpsEl.textContent = 'FPS: ' + avgFps;
    perfHzEl.textContent = 'Hz: ' + perfInstHz;
    perfFrameCount = 0;
    perfSampleStart = now;
  }
  if(!worldActive()) return;
  const dt = Math.min(clock.getDelta(), 0.1);
  simTime += dt;
  updateCamera(dt);
  if(wbFx) wbFx.tick(dt);
  if(legacyMode){
    updateLegacy(dt, simTime);
    updateShards(dt);
    updateTreeGrowth(dt);
    updateSky(simTime);
  } else {
    updateVillagers(dt, simTime);
    updateJobs(dt);
    updateShards(dt);
    updateWeather(simTime, dt);
    updateTreeGrowth(dt);
    updateFarms(simTime);
    updateHouses(simTime);
    updateSky(simTime);
  }
  if(wbFx) wbFx.pre();
  renderer.render(scene, camera);
}
animate();


