// Listen for mode selection from the classic script
window.addEventListener('world:mode-selected', function(e){
  var mode = e.detail.mode;
  if(mode === 'legacy'){
    wbInfRestore();
    if(legacyMode) exitLegacyMode();
    initLegacyMode();
    currentMode = 'legacy';
  } else if(mode === 'infinite'){
    if(wbStartInfiniteCastle()){ checkResumeButton(); return; }
    if(legacyMode) exitLegacyMode();
    if(worldNeedsRegen) regenerateWorld();
    currentMode = 'infinite';
    restoreInfiniteUI();
  } else if(mode === 'load'){
    if(legacyMode) exitLegacyMode();
    if(worldNeedsRegen) regenerateWorld();
    currentMode = 'infinite';
    restoreInfiniteUI();
    document.getElementById('load-file-input').click();
  }
  checkResumeButton();
});

window.addEventListener('world:check-resume', checkResumeButton);

function checkResumeButton(){
  var btn = document.getElementById('mode-resume-btn');
  if(!btn) return;
  var hasGame = (legacyMode && legacyPlayer) || (!legacyMode && world.size > 0);
  btn.style.display = hasGame ? 'block' : 'none';
}

function restoreInfiniteUI(){
  var hud = document.getElementById('legacy-hud');
  var hint = document.getElementById('legacy-hint');
  if(hud) hud.classList.remove('show');
  if(hint) hint.classList.remove('show');
  document.getElementById('hotbar').style.display = '';
  document.getElementById('build-panel-toggle').style.display = '';
  document.getElementById('save-load').style.display = '';
  document.getElementById('mode-toggle').style.display = '';
  var bp = document.getElementById('build-panel');
  if(bp) bp.style.display = '';
  scene.background = new THREE.Color(0x8fc7e8);
  worldFog.color.setHex(0x8fc7e8);
  var gh = document.getElementById('game-hint');
  if(gh) gh.style.display = '';
  // Hide and disable Follow the King button outside Legacy mode
  var followBtn = document.getElementById('follow-king-btn');
  if(followBtn){
    followBtn.disabled = true;
    followBtn.classList.remove('active');
    followBtn.textContent = 'Follow the King';
  }
}

function clearLegacyObjects_base(){
  legacyFactions.forEach(function(f){
    f.units.forEach(function(u){ if(u.group) scene.remove(u.group); });
    f.siegeUnits.forEach(function(u){ if(u.group) scene.remove(u.group); });
    if(f.castle && f.castle.group) scene.remove(f.castle.group);
  });
  legacyFactions = [];
  legacyBuildings.forEach(function(b){ if(b.mesh) scene.remove(b.mesh); });
  legacyBuildings = [];
  legacyOreNodes.forEach(function(o){ if(o.mesh) scene.remove(o.mesh); });
  legacyOreNodes = [];
  legacyPlayer = null;
}

function clearWorld(){
  clearLegacyObjects();
  world.forEach(function(mesh){ scene.remove(mesh); });
  world.clear();
  trees.slice().forEach(function(t){ scene.remove(t.group); });
  trees.length = 0;
  villagers.slice().forEach(function(v){ scene.remove(v.group); });
  villagers.length = 0;
  farms.length = 0;
  houses.length = 0;
  houseDecorMeshes.slice().forEach(function(m){ scene.remove(m); });
  houseDecorMeshes.length = 0;
  shards.slice().forEach(function(s){ scene.remove(s.mesh); s.mesh.material.dispose(); });
  shards.length = 0;
  selectVillager(null);
}

function regenerateWorld(){
  clearWorld();
  buildTerrain();
  treeAttempts = 0;
  while(trees.length < TREE_COUNT && treeAttempts < 1400){
    treeAttempts++;
    var tx = 2 + Math.random()*(WORLD_SIZE-4);
    var tz = 2 + Math.random()*(WORLD_SIZE-4);
    var tooClose = trees.some(function(o){ return Math.hypot(o.x-tx, o.z-tz) < 2.4; });
    if(!tooClose) trees.push(makeTree(tx,tz,0));
  }
  for(var i = villagers.length; i < VILLAGER_COUNT; i++){
    var vx = 4 + Math.random()*(WORLD_SIZE-8);
    var vz = 4 + Math.random()*(WORLD_SIZE-8);
    villagers.push(makeVillager(vx, vz, villagerColors[i % villagerColors.length]));
  }
  inventory.splice(0, inventory.length, 0, 0, 0, 0, 0, 0, 0);
  updateHotbarCounts();
  updateBuildingButtons();
  worldNeedsRegen = false;
  camTarget.set(WORLD_SIZE/2, 0, WORLD_SIZE/2);
  camYaw = Math.PI/4;
  camDistance = 30;
}

// --- Territory helpers ---
function getTerritoryById(id){
  for(var i = 0; i < LEGACY_TERRITORIES.length; i++){
    if(LEGACY_TERRITORIES[i].id === id) return LEGACY_TERRITORIES[i];
  }
  return null;
}

function canReach_old(faction, targetId){
  if(faction.territoryId === targetId) return true;
  if(targetId === 'center') return faction.bridgeBuilt;
  var targetFaction = null;
  for(var i = 0; i < legacyFactions.length; i++){
    if(legacyFactions[i].territoryId === targetId){ targetFaction = legacyFactions[i]; break; }
  }
  if(targetFaction && faction.bridgeBuilt && targetFaction.bridgeBuilt) return true;
  return false;
}

function territoryAtPoint(x, z){
  for(var i = 0; i < LEGACY_TERRITORIES.length; i++){
    var t = LEGACY_TERRITORIES[i];
    var d = Math.hypot(x - t.center.x, z - t.center.z);
    if(d <= t.radius) return t.id;
  }
  return null;
}

// --- Legacy terrain: circular islands ---
function buildLegacyTerrain(){
  LEGACY_TERRITORIES.forEach(function(t){
    var cx = Math.round(t.center.x), cz = Math.round(t.center.z), r = t.radius;
    for(var x = cx - r; x <= cx + r; x++){
      for(var z = cz - r; z <= cz + r; z++){
        var dist = Math.hypot(x - cx, z - cz);
        if(dist <= r){
          addBlock(x, 0, z, 0); // grass
          if(dist > r - 2){
            addBlock(x, 1, z, 2); // stone cliff edge
          }
        }
      }
    }
  });
  // Scatter initial trees in each territory
  LEGACY_TERRITORIES.forEach(function(t){
    if(t.id === 'center') return;
    var count = 6 + Math.floor(Math.random() * 4);
    for(var i = 0; i < count; i++){
      var angle = Math.random() * Math.PI * 2;
      var r = Math.random() * (t.radius - 3);
      var tx = t.center.x + Math.cos(angle) * r;
      var tz = t.center.z + Math.sin(angle) * r;
      var tooClose = trees.some(function(o){ return Math.hypot(o.x-tx, o.z-tz) < 2.5; });
      if(!tooClose) trees.push(makeTree(tx, tz, -1000));
    }
  });
}

