/* ---------- shapes: walls are real oriented boxes now, so they can be turned and joined ---------- */
function wDir(d){ return { x:Math.cos(d.rot), z:-Math.sin(d.rot) }; }      // direction of a wall's long side in the world
function toLocal(d, x, z){ var dx = x - d.x, dz = z - d.z, c = Math.cos(d.rot), s = Math.sin(d.rot); return { x:dx * c - dz * s, z:dx * s + dz * c }; }
