  var ua = { x:Math.cos(a.rot), z:-Math.sin(a.rot) }, va = { x:Math.sin(a.rot), z:Math.cos(a.rot) };
  var ub = { x:Math.cos(b.rot), z:-Math.sin(b.rot) }, vb = { x:Math.sin(b.rot), z:Math.cos(b.rot) };
  var axes = [ua, va, ub, vb], tx = b.x - a.x, tz = b.z - a.z;
