    var n = axes[i];
    var ra = ha[0] * Math.abs(ua.x * n.x + ua.z * n.z) + ha[1] * Math.abs(va.x * n.x + va.z * n.z);
    var rb = hb[0] * Math.abs(ub.x * n.x + ub.z * n.z) + hb[1] * Math.abs(vb.x * n.x + vb.z * n.z);
