var NAMES = { house:['house', 'houses'], farm:['farm', 'farms'], mine:['mine', 'mines'], workshop:['workshop', 'workshops'], market:['market', 'markets'], armory:['armory', 'armories'],
  wall:['wall', 'walls'], tower:['tower', 'towers'], torch:['torch', 'torches'], trap:['trap', 'traps'] };
