  el.querySelector('.sub').textContent = why === 'king' ? 'The zombies overran you. Here is how your run went.' : 'The zombies overran your kingdom. Here is how your run went.';
  el.querySelector('.rows').innerHTML = rows.map(function(r){ return '<div class="row"><span>' + r[0] + '</span><b>' + r[1] + '</b></div>'; }).join('');
